1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { checkInTicket } from "../ticket-actions";
6	import SwitchCashierButton from "../switch-cashier-button";
7	
8	type Category = { id: string; name: string };
9	
10	type CheckResult =
11	  | { kind: "success"; categoryName: string; price: number; invoiceNumber: string; isMemberPrice: boolean }
12	  | { kind: "error"; message: string };
13	
14	function formatRupiah(value: number) {
15	  return `Rp${value.toLocaleString("id-ID")}`;
16	}
17	
18	export default function CheckInScreen({
19	  businessId,
20	  businessName,
21	  cashierId,
22	  cashierName,
23	  categories,
24	}: {
25	  businessId: string;
26	  businessName: string;
27	  cashierId: string;
28	  cashierName: string;
29	  categories: Category[];
30	}) {
31	  const [categoryId, setCategoryId] = useState(categories[0]?.id ?? "");
32	  const [manualNumber, setManualNumber] = useState("");
33	  const [busy, setBusy] = useState(false);
34	  const [result, setResult] = useState<CheckResult | null>(null);
35	  const inputRef = useRef<HTMLInputElement>(null);
36	
37	  useEffect(() => {
38	    inputRef.current?.focus();
39	  }, []);
40	
41	  async function handleSubmit(e: React.FormEvent) {
42	    e.preventDefault();
43	    if (!categoryId || busy) return;
44	
45	    setBusy(true);
46	    const res = await checkInTicket(businessId, cashierId, categoryId, manualNumber);
47	    setBusy(false);
48	    setManualNumber("");
49	    inputRef.current?.focus();
50	
51	    setResult(
52	      res.success
53	        ? {
54	            kind: "success",
55	            categoryName: res.categoryName,
56	            price: res.price,
57	            invoiceNumber: res.invoiceNumber,
58	            isMemberPrice: res.isMemberPrice,
59	          }
60	        : { kind: "error", message: res.error },
61	    );
62	  }
63	
64	  return (
65	    <div className="flex flex-1 flex-col bg-zinc-50 px-4 py-6">
66	      <div className="mx-auto w-full max-w-sm">
67	        <div className="flex items-center justify-between">
68	          <div>
69	            <h1 className="text-lg font-bold text-zinc-900">{businessName}</h1>
70	            <p className="text-xs text-zinc-500">Check-in Tiket · Kasir: {cashierName}</p>
71	          </div>
72	          <Link
73	            href={`/business/${businessId}/pos`}
74	            className="text-xs font-medium text-brand-600 hover:underline"
75	          >
76	            ← Kasir
77	          </Link>
78	        </div>
79	
80	        <form
81	          onSubmit={handleSubmit}
82	          className="mt-4 rounded-xl bg-white shadow-sm p-4"
83	        >
84	          <label className="mb-1 block text-xs font-medium text-zinc-600">Kategori</label>
85	          <select
86	            value={categoryId}
87	            onChange={(e) => setCategoryId(e.target.value)}
88	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
89	          >
90	            {categories.length === 0 && <option value="">Belum ada kategori tiket</option>}
91	            {categories.map((c) => (
92	              <option key={c.id} value={c.id}>
93	                {c.name}
94	              </option>
95	            ))}
96	          </select>
97	
98	          <label className="mb-1 mt-3 block text-xs font-medium text-zinc-600">
99	            No. Tiket Fisik
100	          </label>
101	          <input
102	            ref={inputRef}
103	            type="text"
104	            value={manualNumber}
105	            onChange={(e) => setManualNumber(e.target.value)}
106	            placeholder="Scan / ketik nomor tiket"
107	            className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-base focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
108	          />
109	
110	          <button
111	            type="submit"
112	            disabled={busy || !categoryId}
113	            className="mt-3 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
114	          >
115	            {busy ? "Memeriksa…" : "Cek Tiket"}
116	          </button>
117	        </form>
118	
119	        {result && (
120	          <div
121	            className={`mt-4 rounded-2xl border p-4 text-center ${
122	              result.kind === "success"
123	                ? "border-brand-200 bg-brand-50"
124	                : "border-red-200 bg-red-50"
125	            }`}
126	          >
127	            {result.kind === "success" ? (
128	              <>
129	                <p className="text-2xl">✅</p>
130	                <p className="mt-1 text-sm font-bold text-brand-700">Boleh Masuk</p>
131	                <p className="mt-1 text-sm font-semibold text-zinc-900">
132	                  {result.categoryName}
133	                  {result.isMemberPrice && (
134	                    <span className="ml-1.5 rounded-full bg-brand-100 px-1.5 py-0.5 text-[10px] font-semibold text-brand-700">
135	                      Member
136	                    </span>
137	                  )}
138	                </p>
139	                <p className="text-xs text-zinc-500">
140	                  {result.invoiceNumber} · {formatRupiah(result.price)}
141	                </p>
142	              </>
143	            ) : (
144	              <>
145	                <p className="text-2xl">🚫</p>
146	                <p className="mt-1 text-sm font-bold text-red-700">Tidak Boleh Masuk</p>
147	                <p className="mt-1 text-xs text-red-600">{result.message}</p>
148	              </>
149	            )}
150	          </div>
151	        )}
152	
153	        <SwitchCashierButton />
154	      </div>
155	    </div>
156	  );
157	}
