1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { logActivity } from "@/lib/activity-log";
5	
6	export type TicketCartItemInput = {
7	  ticketCategoryId: string;
8	  manualNumbers: string[];
9	};
10	
11	export type CheckoutTicketResult =
12	  | { success: true; invoiceNumber: string; transactionId: string }
13	  | { success: false; error: string };
14	
15	type CheckoutTicketRpcRow = { transaction_id: string; invoice_number: string };
16	
17	export async function checkoutTicket(
18	  businessId: string,
19	  cashierId: string,
20	  items: TicketCartItemInput[],
21	  paymentMethod: string,
22	  received: number | null,
23	  memberId: string | null = null,
24	): Promise<CheckoutTicketResult> {
25	  if (items.length === 0 || items.every((i) => i.manualNumbers.length === 0)) {
26	    return { success: false, error: "Keranjang masih kosong." };
27	  }
28	
29	  const supabase = await createClient();
30	  const { data, error } = await supabase
31	    .rpc("checkout_ticket_transaction", {
32	      p_business_id: businessId,
33	      p_cashier_id: cashierId,
34	      p_items: items.map((i) => ({
35	        ticket_category_id: i.ticketCategoryId,
36	        manual_numbers: i.manualNumbers,
37	      })),
38	      p_payment_method: paymentMethod,
39	      p_received: received,
40	      p_member_id: memberId,
41	    })
42	    .single();
43	
44	  if (error || !data) {
45	    if (error?.code === "23505") {
46	      return {
47	        success: false,
48	        error: "Nomor tiket fisik ini sudah dipakai untuk kategori ini. Cek kembali nomor booklet.",
49	      };
50	    }
51	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
52	  }
53	
54	  const result = data as CheckoutTicketRpcRow;
55	  const itemCount = items.reduce((sum, i) => sum + i.manualNumbers.length, 0);
56	  await logActivity(
57	    supabase,
58	    businessId,
59	    "transaksi",
60	    "sukses",
61	    `Tiket ${result.invoice_number}`,
62	    `${itemCount} tiket · ${paymentMethod}`,
63	  );
64	
65	  return {
66	    success: true,
67	    invoiceNumber: result.invoice_number,
68	    transactionId: result.transaction_id,
69	  };
70	}
71	
72	export type MemberLookupResult =
73	  | { success: true; member: { id: string; name: string; memberCode: string; validUntil: string } }
74	  | { success: false; error: string };
75	
76	export async function lookupMemberByCode(
77	  businessId: string,
78	  code: string,
79	): Promise<MemberLookupResult> {
80	  const trimmed = code.trim();
81	  if (!trimmed) {
82	    return { success: false, error: "Kode member wajib diisi." };
83	  }
84	
85	  const supabase = await createClient();
86	  const { data, error } = await supabase
87	    .from("members")
88	    .select("id, name, member_code, valid_from, valid_until")
89	    .eq("business_id", businessId)
90	    .eq("member_code", trimmed)
91	    .is("deleted_at", null)
92	    .maybeSingle();
93	
94	  if (error || !data) {
95	    return { success: false, error: "Member tidak ditemukan." };
96	  }
97	
98	  const today = new Date().toISOString().slice(0, 10);
99	  if (today < data.valid_from || today > data.valid_until) {
100	    return { success: false, error: "Membership tidak aktif (kadaluarsa atau belum berlaku)." };
101	  }
102	
103	  return {
104	    success: true,
105	    member: {
106	      id: data.id,
107	      name: data.name,
108	      memberCode: data.member_code,
109	      validUntil: data.valid_until,
110	    },
111	  };
112	}
113	
114	export type VoidTicketResult = { success: true } | { success: false; error: string };
115	
116	export async function voidTicketTransaction(
117	  businessId: string,
118	  transactionId: string,
119	  managerPin: string,
120	  reason: string,
121	): Promise<VoidTicketResult> {
122	  const supabase = await createClient();
123	  const { data, error } = await supabase
124	    .rpc("void_ticket_transaction", {
125	      p_business_id: businessId,
126	      p_transaction_id: transactionId,
127	      p_manager_pin: managerPin,
128	      p_reason: reason || null,
129	    })
130	    .single();
131	
132	  if (error || !data) {
133	    return { success: false, error: error?.message ?? "Gagal membatalkan transaksi." };
134	  }
135	
136	  const row = data as { voided_by_name: string };
137	  await logActivity(
138	    supabase,
139	    businessId,
140	    "transaksi",
141	    "warning",
142	    "Transaksi tiket dibatalkan",
143	    `Oleh ${row.voided_by_name}${reason ? ` · ${reason}` : ""}`,
144	  );
145	
146	  return { success: true };
147	}
148	
149	export type CheckInTicketResult =
150	  | {
151	      success: true;
152	      categoryName: string;
153	      price: number;
154	      isMemberPrice: boolean;
155	      invoiceNumber: string;
156	      soldAt: string;
157	    }
158	  | { success: false; error: string };
159	
160	export async function checkInTicket(
161	  businessId: string,
162	  cashierId: string,
163	  ticketCategoryId: string,
164	  manualNumber: string,
165	): Promise<CheckInTicketResult> {
166	  const trimmed = manualNumber.trim();
167	  if (!trimmed) {
168	    return { success: false, error: "Nomor tiket wajib diisi." };
169	  }
170	
171	  const supabase = await createClient();
172	  const { data, error } = await supabase
173	    .rpc("check_in_ticket", {
174	      p_business_id: businessId,
175	      p_cashier_id: cashierId,
176	      p_ticket_category_id: ticketCategoryId,
177	      p_manual_number: trimmed,
178	    })
179	    .single();
180	
181	  if (error || !data) {
182	    return { success: false, error: error?.message ?? "Gagal memvalidasi tiket." };
183	  }
184	
185	  const row = data as {
186	    category_name: string;
187	    price: number;
188	    is_member_price: boolean;
189	    invoice_number: string;
190	    sold_at: string;
191	  };
192	
193	  await logActivity(
194	    supabase,
195	    businessId,
196	    "transaksi",
197	    "info",
198	    `Check-in tiket ${row.invoice_number}`,
199	    `${row.category_name} · fisik #${trimmed}`,
200	  );
201	
202	  return {
203	    success: true,
204	    categoryName: row.category_name,
205	    price: Number(row.price),
206	    isMemberPrice: row.is_member_price,
207	    invoiceNumber: row.invoice_number,
208	    soldAt: row.sold_at,
209	  };
210	}
