1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import { closeShift, type CloseShiftSummary } from "./actions";
7	import { checkoutTicket, type TicketCartItemInput } from "./ticket-actions";
8	import { calculateTicketTotals, ticketUnitPrice } from "@/lib/ticket-checkout-totals";
9	import SwitchCashierButton from "./switch-cashier-button";
10	import MemberPanel, { type FullMember, type SelectedMember } from "./member-panel";
11	
12	type TicketCategory = {
13	  id: string;
14	  name: string;
15	  priceWeekday: number;
16	  priceHoliday: number;
17	  memberPrice: number;
18	};
19	
20	const BUILTIN_PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
21	
22	function formatRupiah(value: number) {
23	  return `Rp${value.toLocaleString("id-ID")}`;
24	}
25	
26	export default function TicketPosScreen({
27	  businessId,
28	  businessName,
29	  cashierId,
30	  cashierName,
31	  shiftId,
32	  categories,
33	  members,
34	  taxRate,
35	  serviceRate,
36	  isHoliday,
37	  customPaymentMethods,
38	}: {
39	  businessId: string;
40	  businessName: string;
41	  cashierId: string;
42	  cashierName: string;
43	  shiftId: string;
44	  categories: TicketCategory[];
45	  members: FullMember[];
46	  taxRate: number;
47	  serviceRate: number;
48	  isHoliday: boolean;
49	  customPaymentMethods: string[];
50	}) {
51	  const router = useRouter();
52	  const paymentMethods = useMemo(
53	    () => [...BUILTIN_PAYMENT_METHODS, ...customPaymentMethods],
54	    [customPaymentMethods],
55	  );
56	
57	  const [unitsByCategory, setUnitsByCategory] = useState<Record<string, string[]>>({});
58	  const lastAddedRef = useRef<{ categoryId: string; index: number } | null>(null);
59	  const unitInputRefs = useRef<Map<string, HTMLInputElement>>(new Map());
60	
61	  const [member, setMember] = useState<SelectedMember | null>(null);
62	
63	  const [paying, setPaying] = useState(false);
64	  const [paymentMethod, setPaymentMethod] = useState(BUILTIN_PAYMENT_METHODS[0]);
65	  const [received, setReceived] = useState("");
66	  const [submitting, setSubmitting] = useState(false);
67	  const [error, setError] = useState<string | null>(null);
68	  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
69	  const [successTransactionId, setSuccessTransactionId] = useState<string | null>(null);
70	
71	  const [closingShift, setClosingShift] = useState(false);
72	  const [closingCash, setClosingCash] = useState("");
73	  const [closeNotes, setCloseNotes] = useState("");
74	  const [closeError, setCloseError] = useState<string | null>(null);
75	  const [closeSubmitting, setCloseSubmitting] = useState(false);
76	  const [closedSummary, setClosedSummary] = useState<CloseShiftSummary | null>(null);
77	
78	  function unitPriceFor(category: TicketCategory) {
79	    return ticketUnitPrice(category, { isMember: !!member, isHoliday });
80	  }
81	
82	  function addUnit(categoryId: string) {
83	    setUnitsByCategory((prev) => {
84	      const next = [...(prev[categoryId] ?? []), ""];
85	      lastAddedRef.current = { categoryId, index: next.length - 1 };
86	      return { ...prev, [categoryId]: next };
87	    });
88	  }
89	
90	  useEffect(() => {
91	    if (!lastAddedRef.current) return;
92	    const { categoryId, index } = lastAddedRef.current;
93	    lastAddedRef.current = null;
94	    unitInputRefs.current.get(`${categoryId}-${index}`)?.focus();
95	  }, [unitsByCategory]);
96	
97	  function removeUnit(categoryId: string, index: number) {
98	    setUnitsByCategory((prev) => {
99	      const next = { ...prev };
100	      const arr = (next[categoryId] ?? []).filter((_, i) => i !== index);
101	      if (arr.length === 0) {
102	        delete next[categoryId];
103	      } else {
104	        next[categoryId] = arr;
105	      }
106	      return next;
107	    });
108	  }
109	
110	  function setUnitNumber(categoryId: string, index: number, value: string) {
111	    setUnitsByCategory((prev) => {
112	      const arr = [...(prev[categoryId] ?? [])];
113	      arr[index] = value;
114	      return { ...prev, [categoryId]: arr };
115	    });
116	  }
117	
118	  const cartLines = categories
119	    .filter((c) => (unitsByCategory[c.id] ?? []).length > 0)
120	    .map((c) => ({
121	      category: c,
122	      units: unitsByCategory[c.id] ?? [],
123	      unitPrice: unitPriceFor(c),
124	    }));
125	
126	  const { subtotal, serviceAmt, taxAmt, total } = calculateTicketTotals({
127	    lines: cartLines.map((l) => ({ unitPrice: l.unitPrice, qty: l.units.length })),
128	    serviceRate,
129	    taxRate,
130	  });
131	  const receivedAmount = Number(received) || 0;
132	  const change = paymentMethod === "Tunai" ? receivedAmount - total : 0;
133	
134	  async function handleConfirmPayment() {
135	    setError(null);
136	
137	    if (paymentMethod === "Tunai" && receivedAmount < total) {
138	      setError("Uang diterima kurang dari total.");
139	      return;
140	    }
141	
142	    if (cartLines.some((l) => l.units.some((u) => u.trim() === ""))) {
143	      setError("Semua nomor tiket fisik harus diisi.");
144	      return;
145	    }
146	
147	    const items: TicketCartItemInput[] = cartLines.map((l) => ({
148	      ticketCategoryId: l.category.id,
149	      manualNumbers: l.units.map((u) => u.trim()),
150	    }));
151	
152	    setSubmitting(true);
153	    const result = await checkoutTicket(
154	      businessId,
155	      cashierId,
156	      items,
157	      paymentMethod,
158	      paymentMethod === "Tunai" ? receivedAmount : total,
159	      member?.id ?? null,
160	    );
161	    setSubmitting(false);
162	
163	    if (!result.success) {
164	      setError(result.error);
165	      return;
166	    }
167	
168	    setSuccessInvoice(result.invoiceNumber);
169	    setSuccessTransactionId(result.transactionId);
170	  }
171	
172	  async function handleConfirmCloseShift() {
173	    setCloseError(null);
174	
175	    const amount = Number(closingCash);
176	    if (!closingCash || Number.isNaN(amount) || amount < 0) {
177	      setCloseError("Jumlah kas harus angka dan tidak boleh negatif.");
178	      return;
179	    }
180	
181	    setCloseSubmitting(true);
182	    const result = await closeShift(businessId, shiftId, amount, closeNotes);
183	    setCloseSubmitting(false);
184	
185	    if (!result.success) {
186	      setCloseError(result.error);
187	      return;
188	    }
189	
190	    setClosedSummary(result.summary);
191	  }
192	
193	  function resetForNextTransaction() {
194	    setSuccessInvoice(null);
195	    setSuccessTransactionId(null);
196	    setUnitsByCategory({});
197	    setMember(null);
198	    setPaying(false);
199	    setReceived("");
200	    router.refresh();
201	  }
202	
203	  if (successInvoice) {
204	    return (
205	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
206	        <div className="w-full max-w-sm rounded-xl bg-white shadow-sm p-6 text-center">
207	          <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-brand-50 text-2xl">
208	            🎟️
209	          </div>
210	          <h1 className="text-lg font-bold text-zinc-900">Tiket berhasil terbit</h1>
211	          <p className="mt-1 text-sm text-zinc-500">No. Tiket: {successInvoice}</p>
212	          {successTransactionId && (
213	            <Link
214	              href={`/business/${businessId}/ticket-reports/${successTransactionId}/receipt`}
215	              target="_blank"
216	              className="mt-6 block w-full rounded-xl border border-zinc-200 py-2.5 text-sm font-semibold text-zinc-700 transition-colors hover:bg-zinc-50"
217	            >
218	              🖨️ Cetak Struk
219	            </Link>
220	          )}
221	          <button
222	            onClick={resetForNextTransaction}
223	            className="mt-3 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
224	          >
225	            Transaksi Baru
226	          </button>
227	        </div>
228	      </div>
229	    );
230	  }
231	
232	  if (closedSummary) {
233	    const diff = closedSummary.difference;
234	    return (
235	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
236	        <div className="w-full max-w-sm rounded-xl bg-white shadow-sm p-6">
237	          <h1 className="text-center text-lg font-bold text-zinc-900">Shift Ditutup</h1>
238	          <div className="mt-4 space-y-2 text-sm">
239	            <div className="flex justify-between text-zinc-600">
240	              <span>Total Penjualan</span>
241	              <span className="font-medium text-zinc-900">
242	                {formatRupiah(closedSummary.total_sales)}
243	              </span>
244	            </div>
245	            <div className="flex justify-between text-zinc-600">
246	              <span>Penjualan Tunai</span>
247	              <span className="font-medium text-zinc-900">
248	                {formatRupiah(closedSummary.cash_sales)}
249	              </span>
250	            </div>
251	            <div className="flex justify-between text-zinc-600">
252	              <span>Penjualan Non-Tunai</span>
253	              <span className="font-medium text-zinc-900">
254	                {formatRupiah(closedSummary.non_cash_sales)}
255	              </span>
256	            </div>
257	            <div className="flex justify-between text-zinc-600">
258	              <span>Jumlah Transaksi</span>
259	              <span className="font-medium text-zinc-900">{closedSummary.tx_count}</span>
260	            </div>
261	            <div className="flex justify-between border-t border-zinc-100 pt-2 text-zinc-600">
262	              <span>Kas Diharapkan</span>
263	              <span className="font-medium text-zinc-900">
264	                {formatRupiah(closedSummary.expected_cash)}
