158	function useActiveHref(groups: NavGroup[], pathname: string): string | null {
159	  const allHrefs = groups.flatMap((g) => g.items.map((i) => i.href));
160	  const matches = allHrefs.filter((h) => pathname === h || pathname.startsWith(`${h}/`));
161	  if (matches.length === 0) return null;
162	  return matches.sort((a, b) => b.length - a.length)[0];
163	}
164	
165	function activeGroupTitleOf(groups: NavGroup[], activeHref: string | null): string | null {
166	  if (!activeHref) return groups[0]?.title ?? null;
167	  return groups.find((g) => g.items.some((i) => i.href === activeHref))?.title ?? groups[0]?.title ?? null;
168	}
