13	const DONUT_PALETTE = ["#0f766e", "#34d399", "#fcd34d", "#a78bfa", "#fb923c", "#60a5fa", "#f87171"];
14	
15	function formatRupiah(value: number) {
16	  const sign = value < 0 ? "-" : "";
17	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
18	}
