30	const hourFormatter = new Intl.DateTimeFormat("en-US", {
31	  hour: "numeric",
32	  hourCycle: "h23",
33	  timeZone: REPORT_TIMEZONE,
34	});
35	
36	function wibHour(iso: string) {
37	  return Number(hourFormatter.format(new Date(iso)));
38	}
