40	function buildDonutSegments(entries: [string, number][], total: number) {
41	  const R = 28;
42	  const cx = 40;
43	  const cy = 40;
44	  // Satu metode = lingkaran penuh; path arc 360° akan degenerate (titik awal == akhir).
45	  if (entries.length === 1) {
46	    return [{ d: null, color: DONUT_PALETTE[0] }];
47	  }
48	  let angle = -Math.PI / 2;
49	  return entries.map(([, val], i) => {
50	    const sweep = (val / total) * 2 * Math.PI;
51	    const x1 = cx + R * Math.cos(angle);
52	    const y1 = cy + R * Math.sin(angle);
53	    const x2 = cx + R * Math.cos(angle + sweep);
54	    const y2 = cy + R * Math.sin(angle + sweep);
55	    const large = sweep > Math.PI ? 1 : 0;
56	    angle += sweep;
57	    return {
58	      d: `M${cx},${cy} L${x1},${y1} A${R},${R} 0 ${large},1 ${x2},${y2} Z`,
59	      color: DONUT_PALETTE[i % DONUT_PALETTE.length],
60	    };
61	  });
62	}
